CREATE TABLE orders (
  order_id    NUMBER        PRIMARY KEY,
  customer    VARCHAR2(50)  NOT NULL,
  amount      NUMBER(10,2)  NOT NULL,
  status      VARCHAR2(20)  DEFAULT 'NEW' NOT NULL
);

INSERT INTO orders VALUES (1, 'Asha',   1200.00, 'NEW');
INSERT INTO orders VALUES (2, 'Ravi',    450.50, 'PAID');
INSERT INTO orders VALUES (3, 'Meera',  3100.00, 'NEW');
INSERT INTO orders VALUES (4, 'John',    780.00, 'SHIPPED');
COMMIT;

-- Session A
COMMIT;

-- Session B
TRUNCATE TABLE orders;

-- Session B
ALTER SESSION SET ddl_lock_timeout = 60;

TRUNCATE TABLE orders;

DECLARE
  e_row_locked EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_row_locked, -54);

  v_status orders.status%TYPE;
BEGIN
  SELECT status
    INTO v_status
    FROM orders
   WHERE order_id = 1
     FOR UPDATE NOWAIT;

  UPDATE orders
     SET status = 'SHIPPED'
   WHERE order_id = 1;

  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Order 1 updated');
EXCEPTION
  WHEN e_row_locked THEN
    DBMS_OUTPUT.PUT_LINE('Order 1 is being edited by another session. Try again later.');
END;
/

BEGIN
  EXECUTE IMMEDIATE 'ALTER SESSION SET ddl_lock_timeout = 30';
  EXECUTE IMMEDIATE 'TRUNCATE TABLE orders_stage';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE = -54 THEN
      DBMS_OUTPUT.PUT_LINE('orders_stage still locked after 30 seconds');
    END IF;
    RAISE;
END;
/

