-- ORA-00054: resource busy

ALTER SESSION SET ddl_lock_timeout = 30;

TRUNCATE TABLE orders;

CREATE INDEX orders_cust_ix
  ON orders (customer) ONLINE;

DECLARE
  e_busy EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_busy, -54);
BEGIN
  NULL; -- SELECT ... FOR UPDATE NOWAIT
EXCEPTION
  WHEN e_busy THEN
    DBMS_OUTPUT.PUT_LINE('Row is busy');
END;
